  scope=[['Başlangıç değerlendirmesi', 'Hesapların durumu, hedefler ve marka tonu'], ['İçerik planı', 'Aylık takvim, içerik türleri ve konu başlıkları'], ['Tasarım ve metin', 'Görsel, kısa video ve gönderi metinleri'], ['Yayın ve onay düzeni', 'Hangi içeriğin kimin onayından geçtiği'], ['Topluluk yönetimi', 'Yorum ve mesaj yanıt çerçevesi'], ['Raporlama', 'Dönemsel etkileşim, trafik ve öneriler']],
  deep=[('Hedefsiz paylaşım yorucudur', 'Her gün paylaşım yapmak başlı başına bir hedef değildir. Önce hesabın ne için kullanılacağını (bilinirlik, talep, destek) belirler, içerik türlerini bu amaca göre seçeriz. İçerikler üretilmeden önce aylık plan ve onay düzeni oluşturulur.'), ('Üretim ve onay düzeni', 'Çekim, tasarım ve metin üretiminin kimde olacağı baştan yazılır. Onay süreçleri uzadığında yayın aksar; bu nedenle onay kişisini ve süresini belirleriz. Acil duyurular için kısa bir hızlı onay yolu tanımlanabilir.'), ('Topluluk yönetiminde dikkat edilecekler', 'Yorum ve mesajlara dönüş hızı, işletmenizin algısını etkiler. Sık sorulan sorular için yanıt çerçevesi hazırlar, şikâyet ve hassas konular için ne zaman sizin ekibinize yönlendirileceğini belirleriz.')],
  cardsH='Sosyal medya yönetiminde hangi işleri yapıyoruz?',
  cards=[('İçerik planı ve takvim', 'Aylık içerik takvimi, konu başlıkları ve yayın düzenini hazırlarız.'), ('Tasarım ve gönderi metni', 'Marka tonuna uygun görsel ve metinler hazırlar, onayınıza sunarız.'), ('Topluluk yönetimi', 'Yorum ve mesajlar için yanıt düzeni ve yönlendirme kuralları belirleriz.'), ('Raporlama', 'Etkileşim, site trafiği ve talepleri birlikte okuyup sonraki dönem önerileri yazarız.')],
