  steps=[('İşletmenizi ve hedefinizi tanıyalım', 'Hesaplarınızın bugünkü durumunu, hedef kitlenizi ve sosyal medyadan beklentinizi dinleriz.'), ('Kapsam ve sorumlulukları netleştirelim', 'Hangi hesapların, hangi sıklıkla ve kim tarafından yönetileceğini yazılı hale getiririz.'), ('Erişimleri ve ölçümü kontrol edelim', 'Hesap erişimleri platform yetkileriyle verilir; takip bağlantıları ve rapor düzeni kurulur.'), ('İçerik planını hazırlayalım', 'Aylık takvim, içerik fikirleri ve ilk gönderiler hazırlanır; onayınızdan sonra yayına alınır.'), ('Yayın ve ilk değerlendirmeyi yapalım', 'İçeriklerin etkileşimi izlenir, ilk dönem sonunda hangi içerik türlerinin sürdürüleceğine birlikte karar verilir.')],
  needs='Hesaplarınızın adresleri, marka materyalleriniz, hedef kitleniz ve onay verecek kişi yeterli bir başlangıçtır. Şifre paylaşmanız gerekmez; erişim platformların yetkilendirme araçlarıyla verilir.',
  scen=[('Yerel kafe için örnek çalışma senaryosu', 'Bir kafenin hesabı düzenli paylaşım yapıyor ama masa rezervasyonu gelmiyor. Paylaşımların sonunda yönlendirme olup olmadığı ve profil bağlantısının doğruluğu incelenir. Örnek yaklaşımda içeriklere rezervasyon çağrısı ve takip bağlantısı eklenir. Değerlendirme rezervasyon talepleriyle yapılır.'), ('Hukuk bürosu için örnek çalışma senaryosu', 'Bir hukuk bürosu bilgilendirici paylaşımlar yapıyor ama görüşme talebi gelmiyor. İçeriklerin dili ve çağrı düzeni gözden geçirilir. Örnek yaklaşımda konu başlıkları sık sorulan sorulara göre seçilir ve profilde net bir iletişim yolu sunulur. Başarı etkileşimle değil, uygun görüşme talebiyle değerlendirilir.')],
  costRows=[['Yönetim bedeli', 'PakSoft’a', 'Hesap sayısına ve paylaşım sıklığına göre belirlenir'], ['İçerik üretimi', 'PakSoft veya sizin ekibiniz', 'Tasarım, video ve çekim kapsamı'], ['Reklam bütçesi', 'Varsa platforma', 'Ücretli tanıtım yapılacaksa ayrı planlanır'], ['Araç ve lisans', 'Gerekiyorsa size veya PakSoft’a', 'Planlama ve tasarım araçlarına göre değişir']],
  factors=[('Hesap sayısı', 'Yönetilen platform ve hesap sayısı'), ('Paylaşım sıklığı', 'Haftalık içerik adedi'), ('Üretim kapsamı', 'Görsel, video ve çekim ihtiyacı'), ('Topluluk yönetimi', 'Yorum ve mesaj dönüş kapsamı'), ('Rapor düzeni', 'Rapor sıklığı ve toplantılar')],
  faq=[('Sosyal medya yönetimi neleri kapsar?', 'İçerik planı, tasarım ve metin, yayın, topluluk yönetimi ve raporlama kapsama girebilir; teklifte yazılı olarak belirlenir.'), ('Hangi platformlarla çalışıyorsunuz?', 'Instagram, Facebook, LinkedIn ve TikTok gibi platformlar için çalışabiliriz; hedefinize göre uygun olanları birlikte seçeriz.'), ('İçerikleri kim üretir?', 'Kapsama göre değişir; çekim, tasarım ve metin üretimini biz yapabilir veya sizin materyallerinizle çalışabiliriz.'), ('Her paylaşımı onaylamam gerekir mi?', 'Onay düzenini birlikte belirleriz. Aylık plan onayı ve tekil paylaşım onayı arasında seçim yapabilirsiniz.'),
       ('Ne kadar sürede sonuç alırım?', 'Sosyal medyada sonuçlar zamanla birikir; kesin bir tarih vermeyiz.'), ('Takipçi sayısı garanti ediliyor mu?', 'Hayır. Takipçi veya erişim sayısı için söz vermeyiz; sonuçları ölçüm ve raporla şeffaf gösteririz.'), ('Reklam bütçesi dahil mi?', 'Hayır. Ücretli tanıtım yapılacaksa bütçe platforma ödenir ve teklifte ayrı yazılır.'), ('Mevcut hesaplarımla çalışabilir miyiz?', 'Evet. Hesabın durumunu inceleyip mevcut yapı üzerinden ilerleyebiliriz.')],
